//! About Ordia screen displaying version, `Apache-2.0` license, and embedded third-party notices (`M1-08`).

use gpui_kit::base::StyledExt as _;
use gpui_kit::component::{
    ActiveTheme as _, Sizable as _, button::Button, h_flex, scroll::ScrollableElement as _, v_flex,
};
use gpui_kit::{
    Context, InteractiveElement as _, IntoElement, ParentElement as _, SharedString, Styled as _,
    div, px,
};
use ordia_ui::OrdiaTokens;

use crate::MainWindow;

/// Compile-time embedded third-party open-source notices generated by `cargo xtask bundle`.
pub const EMBEDDED_THIRD_PARTY_LICENSES: &str =
    include_str!("../../../assets/THIRD_PARTY_LICENSES.txt");

/// Returns the current Ordia application SemVer version.
#[must_use]
pub const fn app_version() -> &'static str {
    env!("CARGO_PKG_VERSION")
}

/// Returns Ordia's open-source SPDX license identifier.
#[must_use]
pub const fn app_license() -> &'static str {
    env!("CARGO_PKG_LICENSE")
}

/// Parses non-comment `crate | version | license | repo` lines from [`EMBEDDED_THIRD_PARTY_LICENSES`].
#[must_use]
pub fn third_party_notice_lines() -> Vec<&'static str> {
    EMBEDDED_THIRD_PARTY_LICENSES
        .lines()
        .map(str::trim)
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .collect()
}

impl MainWindow {
    /// Returns whether the About Ordia screen is currently open.
    #[must_use]
    pub fn is_showing_about(&self) -> bool {
        self.show_about
    }

    /// Opens the About Ordia view (`Help -> About Ordia`).
    pub fn open_about_screen(&mut self, cx: &mut Context<Self>) {
        self.show_settings = false;
        self.show_about = true;
        cx.notify();
    }

    /// Closes the About Ordia view and returns to the active workbook or Home view.
    pub fn close_about_screen(&mut self, cx: &mut Context<Self>) {
        if self.show_about {
            self.show_about = false;
            cx.notify();
        }
    }

    pub(crate) fn render_about_screen(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let tokens = OrdiaTokens::for_mode(cx.theme().mode);
        let lines = third_party_notice_lines();
        let count_str = lines.len().to_string();
        let preview_text = SharedString::from(
            lines
                .iter()
                .copied()
                .take(150)
                .collect::<Vec<_>>()
                .join("\n"),
        );

        v_flex()
            .id("ordia-about-screen")
            .flex_1()
            .size_full()
            .overflow_y_scrollbar()
            .p(tokens.spacing.xl)
            .gap(tokens.spacing.lg)
            .bg(cx.theme().background)
            .child(
                h_flex()
                    .justify_between()
                    .items_center()
                    .child(
                        v_flex()
                            .gap(tokens.spacing.xxs)
                            .child(
                                div()
                                    .text_lg()
                                    .font_semibold()
                                    .child(ordia_i18n::t!("about.title")),
                            )
                            .child(
                                div()
                                    .text_xs()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(ordia_i18n::t!("about.subtitle")),
                            ),
                    )
                    .child(
                        Button::new("about-close")
                            .outline()
                            .small()
                            .label(ordia_i18n::t!("about.close_btn"))
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.close_about_screen(cx);
                            })),
                    ),
            )
            .child(
                v_flex()
                    .p(tokens.spacing.lg)
                    .gap(tokens.spacing.xs)
                    .rounded(tokens.radius.md)
                    .border_1()
                    .border_color(cx.theme().border)
                    .bg(cx.theme().popover)
                    .child(
                        div().text_sm().font_semibold().child(
                            ordia_i18n::t!("about.version_label", "version" => app_version()),
                        ),
                    )
                    .child(div().text_xs().child(ordia_i18n::t!("about.license_label")))
                    .child(
                        div()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(ordia_i18n::t!("about.repo_label")),
                    ),
            )
            .child(
                v_flex()
                    .p(tokens.spacing.lg)
                    .gap(tokens.spacing.sm)
                    .rounded(tokens.radius.md)
                    .border_1()
                    .border_color(cx.theme().border)
                    .bg(cx.theme().popover)
                    .child(
                        div().text_sm().font_semibold().child(
                            ordia_i18n::t!("about.third_party_heading", "count" => count_str),
                        ),
                    )
                    .child(
                        div()
                            .id("about-licenses-scroll")
                            .max_h(px(320.))
                            .overflow_y_scrollbar()
                            .p(tokens.spacing.sm)
                            .rounded(tokens.radius.sm)
                            .bg(cx.theme().secondary)
                            .text_xs()
                            .child(preview_text),
                    ),
            )
    }
}
